<script lang="ts">
	import {onMount} from 'svelte'; import RefreshCwIcon from '@lucide/svelte/icons/refresh-cw'; import PlusIcon from '@lucide/svelte/icons/plus'; import {listEvidence,createEvidence,deleteEvidence,restoreEvidence,type Evidence,type EvidenceFilters,type EvidenceSortKey} from './assertion-evidence-client';
	let {darkMode=true}:{darkMode:boolean}=$props(); let bg=$derived(darkMode?'#171B26':'#F2F4F7'),card=$derived(darkMode?'#1F2333':'#FFFFFF'),surface=$derived(darkMode?'#252A3A':'#ECEEF2'),border=$derived(darkMode?'#2D3348':'#E4E6EB'),accent=$derived(darkMode?'#818CF8':'#6366F1'),text=$derived(darkMode?'#E2E8F0':'#111827'),muted=$derived(darkMode?'#94A3B8':'#6B7280'),danger=$derived(darkMode?'#F87171':'#DC2626');
	let rows=$state<Evidence[]>([]),total=$state(0),page=$state(1),pageSize=$state(50),loading=$state(false),saving=$state(false),error=$state(''),info=$state(''),selected=$state<Evidence|null>(null),showCreate=$state(false),reason=$state(''),sortBy=$state<EvidenceSortKey|''>('created'),sortDir=$state<'asc'|'desc'>('desc'); let filters=$state<EvidenceFilters>({assertion_id:'',input_record_id:'',artifact_type:'',artifact_id:'',evidence_role:'',actor_kind:'',include_deleted:false}); let form=$state({assertion_id:'',input_record_id:'',artifact_type:'',artifact_id:'',evidence_quote:'',evidence_role:'supports',actor_kind:'processor',confidence:'',extraction_run:'',model:'',prompt_version:''}); const pageSizeOptions=[25,50,100,200]; const sortableHeaders:{key:EvidenceSortKey;label:string}[]=[{key:'assertion',label:'Assertion ID'},{key:'input_record',label:'Input Record ID'},{key:'artifact',label:'Artifact'},{key:'role',label:'Role'},{key:'confidence',label:'Confidence'},{key:'deleted',label:'Deleted'},{key:'created',label:'Created'}];
	async function load(){loading=true;error='';try{const r=await listEvidence(filters,page,pageSize,sortBy||undefined,sortDir);rows=r.results;total=r.total}catch(e){error=e instanceof Error?e.message:String(e)}finally{loading=false}} function apply(){page=1;load()} function changePageSize(v:string){pageSize=Number(v);page=1;load()} function toggle(k:EvidenceSortKey){if(sortBy===k)sortDir=sortDir==='asc'?'desc':'asc';else{sortBy=k;sortDir='asc'}page=1;load()} function time(v:string){const d=new Date(v);return Number.isNaN(d.getTime())?v:d.toLocaleString()} function json(v:unknown){try{return JSON.stringify(v,null,2)}catch{return String(v)}} async function create(){saving=true;try{await createEvidence({...form,assertion_id:Number(form.assertion_id),input_record_id:form.input_record_id?Number(form.input_record_id):undefined,confidence:form.confidence?Number(form.confidence):undefined});showCreate=false;info='Evidence created.';await load()}catch(e){error=e instanceof Error?e.message:String(e)}finally{saving=false}} async function remove(){if(!selected)return;saving=true;try{selected=await deleteEvidence(selected.id,{reason});info='Evidence soft-deleted.';await load()}catch(e){error=e instanceof Error?e.message:String(e)}finally{saving=false}} async function restore(){if(!selected)return;saving=true;try{selected=await restoreEvidence(selected.id);info='Evidence restored.';await load()}catch(e){error=e instanceof Error?e.message:String(e)}finally{saving=false}} onMount(load);
</script>
<div class="h-full space-y-4 overflow-auto p-6" style="background:{bg}"><div class="rounded-xl p-5" style="background:{card};border:1px solid {border}"><div class="flex flex-wrap items-start justify-between gap-3"><div><h2 style="font-size:18px;font-weight:600;color:{text}">Assertion Evidence</h2><p style="font-size:13px;color:{muted};margin-top:2px">Lifecycle-safe administration of <code style="color:{accent}">kb.assertion_evidence</code>.</p></div><div class="flex gap-2"><button onclick={()=>showCreate=true} class="rounded-lg px-3 py-2 text-sm" style="background:{accent};color:white"><PlusIcon class="inline h-4 w-4" /> New Evidence</button><button onclick={load} disabled={loading} class="rounded-lg px-3 py-2 text-sm" style="background:{surface};color:{text};border:1px solid {border}"><RefreshCwIcon class="inline h-4 w-4" /> Refresh</button></div></div></div>
	<div class="rounded-xl p-5" style="background:{card};border:1px solid {border}"><div class="grid gap-3 md:grid-cols-3"><label style="color:{muted}">Assertion ID<input bind:value={filters.assertion_id} class="w-full rounded px-2 py-1.5 text-sm" style="background:{surface};color:{text};border:1px solid {border}" /></label><label style="color:{muted}">Input Record ID<input bind:value={filters.input_record_id} class="w-full rounded px-2 py-1.5 text-sm" style="background:{surface};color:{text};border:1px solid {border}" /></label><label style="color:{muted}">Artifact Type<input bind:value={filters.artifact_type} class="w-full rounded px-2 py-1.5 text-sm" style="background:{surface};color:{text};border:1px solid {border}" /></label><label style="color:{muted}">Artifact ID<input bind:value={filters.artifact_id} class="w-full rounded px-2 py-1.5 text-sm" style="background:{surface};color:{text};border:1px solid {border}" /></label><label style="color:{muted}">Role<select bind:value={filters.evidence_role} class="w-full rounded px-2 py-1.5 text-sm" style="background:{surface};color:{text};border:1px solid {border}"><option value="">Any</option><option>supports</option><option>contradicts</option></select></label><label style="color:{muted}">Actor<select bind:value={filters.actor_kind} class="w-full rounded px-2 py-1.5 text-sm" style="background:{surface};color:{text};border:1px solid {border}"><option value="">Any</option><option>processor</option><option>human</option></select></label></div><label class="mt-3 flex items-center gap-2 text-sm" style="color:{muted}"><input type="checkbox" bind:checked={filters.include_deleted} onchange={apply}/> Include deleted</label><button onclick={apply} class="mt-3 rounded-lg px-3 py-2 text-sm" style="background:{accent};color:white">Apply Filters</button></div>
	{#if error}<div class="rounded-xl p-4" style="background:{danger}20;color:{danger}">{error}</div>{/if}{#if info}<div class="rounded-xl p-4" style="background:{accent}20;color:{accent}">{info}</div>{/if}<div class="overflow-hidden rounded-xl" style="background:{card};border:1px solid {border}"><div class="flex justify-between px-5 py-3 text-sm" style="border-bottom:1px solid {border};color:{muted}">Total: {total}<div class="flex items-center gap-2"><button onclick={()=>{if(page>1){page--;load()}}} disabled={page<=1||loading}>‹</button><label class="flex items-center gap-2"><span>Page Size</span><select value={pageSize} onchange={e=>changePageSize((e.currentTarget as HTMLSelectElement).value)} disabled={loading} class="rounded px-2 py-1" style="background:{surface};color:{text};border:1px solid {border}">{#each pageSizeOptions as option}<option value={option}>{option}</option>{/each}</select></label>Page {page} of {Math.max(1,Math.ceil(total/pageSize))}<button onclick={()=>{if(page<Math.ceil(total/pageSize)){page++;load()}}} disabled={page>=Math.ceil(total/pageSize)||loading}>›</button></div></div>{#if loading}<div class="p-8 text-center" style="color:{muted}">Loading…</div>{:else}<div class="overflow-auto"><table class="w-full text-left text-sm"><thead style="color:{muted}"><tr>{#each sortableHeaders as h}<th class="px-4 py-3"><button type="button" onclick={()=>toggle(h.key)} aria-label={`Sort by ${h.label}`} style="color:{muted};background:none;border:0;padding:0">{h.label}{#if sortBy===h.key}<span aria-hidden="true">{sortDir==='asc'?'↑':'↓'}</span>{:else}<span aria-hidden="true"> ↕</span>{/if}</button></th>{/each}<th class="px-4 py-3">Details</th></tr></thead><tbody>{#each rows as row}<tr class="cursor-pointer" style="border-top:1px solid {border};color:{text}" onclick={()=>selected=row}><td class="px-4 py-3">{row.assertion_id}</td><td class="px-4 py-3">{row.input_record_id??'—'}</td><td class="px-4 py-3">{row.artifact_type}:{row.artifact_id}</td><td class="px-4 py-3">{row.evidence_role}</td><td class="px-4 py-3">{row.confidence??'—'}</td><td class="px-4 py-3">{row.deleted?'Yes':'No'}</td><td class="px-4 py-3">{time(row.create_time)}</td><td class="px-4 py-3">View</td></tr>{/each}</tbody></table></div>{/if}</div>
	{#if selected}<div class="rounded-xl p-5" style="background:{card};border:1px solid {border}"><div class="flex justify-between"><h3 style="color:{text};font-weight:600">Evidence #{selected.id}</h3><button onclick={()=>selected=null} style="color:{muted}">Close</button></div><pre class="mt-3 max-h-72 overflow-auto rounded p-3 text-xs" style="background:{surface};color:{text}">{json(selected)}</pre>{#if selected.deleted}<button onclick={restore} disabled={saving} class="mt-3 rounded px-3 py-2 text-sm" style="background:{accent};color:white">Restore</button>{:else}<div class="mt-3 flex gap-2"><input placeholder="Deletion reason" bind:value={reason} class="rounded px-2 py-2 text-sm" style="background:{surface};color:{text};border:1px solid {border}" /><button onclick={remove} disabled={saving} class="rounded px-3 py-2 text-sm" style="background:{danger};color:white">Soft Delete</button></div>{/if}</div>{/if}
	{#if showCreate}<div class="rounded-xl p-5" style="background:{card};border:1px solid {border}"><h3 style="color:{text};font-weight:600">Create Evidence</h3><div class="mt-3 grid gap-3 md:grid-cols-2">{#each [['assertion_id','Assertion ID'],['input_record_id','Input Record ID'],['artifact_type','Artifact Type'],['artifact_id','Artifact ID'],['confidence','Confidence'],['extraction_run','Extraction Run'],['model','Model'],['prompt_version','Prompt Version']] as f}<label style="color:{muted}">{f[1]}<input bind:value={form[f[0] as keyof typeof form]} class="w-full rounded px-2 py-1.5 text-sm" style="background:{surface};color:{text};border:1px solid {border}" /></label>{/each}<label style="color:{muted}">Role<select bind:value={form.evidence_role} class="w-full rounded px-2 py-1.5 text-sm" style="background:{surface};color:{text};border:1px solid {border}"><option>supports</option><option>contradicts</option></select></label><label style="color:{muted}">Actor<select bind:value={form.actor_kind} class="w-full rounded px-2 py-1.5 text-sm" style="background:{surface};color:{text};border:1px solid {border}"><option>processor</option><option>human</option></select></label></div><label class="mt-3 block" style="color:{muted}">Evidence Quote<textarea bind:value={form.evidence_quote} rows="3" class="w-full rounded px-2 py-1.5 text-sm" style="background:{surface};color:{text};border:1px solid {border}"></textarea></label><div class="mt-3 flex gap-2"><button onclick={create} disabled={saving} class="rounded px-3 py-2 text-sm" style="background:{accent};color:white">Save</button><button onclick={()=>showCreate=false} class="rounded px-3 py-2 text-sm" style="background:{surface};color:{text};border:1px solid {border}">Cancel</button></div></div>{/if}
</div>
